# Check if cyan_pen is already inside magenta_holder
res = check("cyan_pen", "magenta_holder")
if not res.get("satisfied", False):
    obs = observe()
    pen = obs["objects"]["cyan_pen"]
    holder = obs["zones"]["magenta_holder"]

    # Pick a grasp candidate across short axis or high enough on the pen
    candidates = grasp_candidates("cyan_pen")
    valid_candidates = [
        c for c in candidates 
        if c.get("fits_open_fingers", True) and c.get("hand_clear", True)
    ]
    if valid_candidates:
        candidate = max(valid_candidates, key=lambda c: c.get("score", 0))
    else:
        candidate = candidates[0]

    # If the pen is tall/leaning, ensure height is well-positioned
    if pen["height"] > 0.08:
        candidate["height"] = max(0.06, min(pen["height"] * 0.6, 0.08))

    grasp_res = grasp(candidate)
    if grasp_res.get("holding_something", False):
        drop_into_container_v2("cyan_pen", "magenta_holder", safe_z_offset=0.08)

go_home()
